// The teletext renderer's limits of a sub-page's animation, its controls and
// its object pages (animation.md ANIM-16, ANIM-17; EN 300 706 clause 10.5.1),
// generated by scripts/picture-limits.ts from the renderer's files, their one
// home:
//   crates/neoteletext-core/src/limits.rs
//   crates/neoteletext-core/src/controls.rs
//   crates/neoteletext-core/src/consts/object_pages.rs
//   crates/neoteletext-picture/src/tti.rs
// at the commit scripts/check.sh names (LIMITS_FROM), which checks this copy against them.
// Each keeps the renderer's name: write a limit by its name, never its
// figure. Do not edit this file; generate it.

/**
 * The layers of a page (ANIM-12): 0 the page's own picture, 1 the scene,
 * 2 sprites, 3 the overlay.
 */
export const LAYERS = 4;
/** The sprites of a teletext sub-page (ANIM-7, ANIM-16). */
export const MAX_SPRITES = 32;
/**
 * The sprites and controls of a sub-page that hold animation state at
 * once (ANIM-6, ANIM-16).
 */
export const MAX_ANIMATED_OBJECTS = 32;
/** The objects of a page whose frames cycle at once (ANIM-14, ANIM-16). */
export const MAX_CYCLING_OBJECTS = 16;
/** The frames of an object (ANIM-14, ANIM-16). */
export const MAX_OBJECT_FRAMES = 16;
/**
 * The most controls a page has: a control triplet beyond them is dropped
 * (REQ-INT-118). A page's 208 local triplets could declare more, one a
 * triplet, but a page of 23 rows holds no more distinct things to press
 * than a list down it and a row of buttons.
 */
export const MAX_CONTROLS = 32;
/** The object types: Active, Adaptive and Passive (Table 28). */
export const OBJECT_TYPES = 3;
/**
 * Objects of one type on one object sub-page: packets 1 to 4
 * (clause 10.5.1.1).
 */
export const OBJECTS_PER_TYPE = 32;
/** Sub-pages of an object page: S1 is four bits (EN 300 706 Annex A.1). */
export const OBJECT_SUBPAGES = 16;
